'use strict';

// Line diff for the code review screen. Both versions of a file arrive as one
// string; the screen renders one row per line of whatever comes back.

function splitLines(text) {
  return String(text).split('\n');
}

// Walks the two versions position by position. Fine while both sides are the
// same length and nothing has moved.
function diffLines(a, b) {
  const left = splitLines(a);
  const right = splitLines(b);
  const ops = [];
  const rows = Math.max(left.length, right.length);
  for (let i = 0; i < rows; i += 1) {
    if (i < left.length && i < right.length && left[i] === right[i]) {
      ops.push({ type: 'equal', line: left[i] });
    } else {
      if (i < left.length) ops.push({ type: 'delete', line: left[i] });
      if (i < right.length) ops.push({ type: 'insert', line: right[i] });
    }
  }
  return ops;
}

module.exports = { splitLines, diffLines };

