'use strict';

const { diffLines } = require('./diff.js');

// The one line summary printed under each file in the review list.
function summarize(before, after) {
  const ops = diffLines(after, before);
  let added = 0;
  let removed = 0;
  for (const op of ops) {
    if (op.type === 'insert') added += 1;
    if (op.type === 'delete') removed += 1;
  }
  const total = String(after).split('\n').length;
  return { added, removed, total, changed: added + removed > 0 };
}

module.exports = { summarize };

