'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { splitLines, trimCommon, diffLines, hunks, unified, sideBySide } = require('./src/diff.js');
const { summarize } = require('./src/review.js');

// A file of numbered lines, so every line is unique and the alignment between
// two versions of it is never ambiguous.
function numbered(count) {
  const out = [];
  for (let i = 1; i <= count; i += 1) out.push('L' + String(i).padStart(2, '0'));
  return out;
}
const text = (arr) => arr.join('\n') + '\n';
const shape = (ops) => ops.map((op) => op.type + '|' + op.line);
const replaceAt = (arr, index, value) => {
  const copy = arr.slice();
  copy[index] = value;
  return copy;
};

test('s1 splitting stops inventing a final empty line', () => {
  assert.deepStrictEqual(splitLines('alpha\nbeta\n'), ['alpha', 'beta'], 'a trailing newline closes the last line, it does not start another');
  assert.deepStrictEqual(splitLines('alpha\nbeta'), ['alpha', 'beta'], 'a file that stops without a newline still has its last line');
  assert.deepStrictEqual(splitLines('one'), ['one']);
  assert.deepStrictEqual(splitLines(''), [], 'an empty file has no lines at all');
  assert.deepStrictEqual(splitLines('\n'), [''], 'a lone newline is one empty line');
  assert.deepStrictEqual(splitLines('\n\n'), ['', ''], 'two newlines are two empty lines');
  assert.deepStrictEqual(splitLines('a\n\nb\n'), ['a', '', 'b'], 'a blank line in the middle survives');

  const same = diffLines('alpha\nbeta\n', 'alpha\nbeta\n');
  assert.strictEqual(same.length, 2, 'no phantom row reaches the op list either');
  assert.deepStrictEqual(shape(same), ['equal|alpha', 'equal|beta']);
});

test('s2 trimCommon counts the shared head and tail without counting a line twice', () => {
  assert.deepStrictEqual(trimCommon(['a', 'b', 'c'], ['a', 'x', 'c']), { prefix: 1, suffix: 1 });
  assert.deepStrictEqual(trimCommon(['a', 'b', 'c', 'd'], ['a', 'b', 'c', 'd']), { prefix: 4, suffix: 0 }, 'identical sides are all prefix');
  assert.deepStrictEqual(trimCommon(['x', 'a', 'b'], ['a', 'b']), { prefix: 0, suffix: 2 });
  assert.deepStrictEqual(trimCommon(['a', 'b'], ['a', 'b', 'c']), { prefix: 2, suffix: 0 });
  assert.deepStrictEqual(trimCommon(['q', 'r'], ['s', 't']), { prefix: 0, suffix: 0 });

  // The overlap trap: the prefix has already taken every line of the shorter
  // side, so there is nothing left for the suffix to claim.
  assert.deepStrictEqual(trimCommon(['a', 'a', 'a'], ['a', 'a']), { prefix: 2, suffix: 0 });
  assert.deepStrictEqual(trimCommon(['a', 'a'], ['a', 'a', 'a']), { prefix: 2, suffix: 0 });
  const spanning = trimCommon(['z', 'z', 'z', 'z'], ['z', 'z']);
  assert.strictEqual(spanning.prefix + spanning.suffix <= 2, true, 'the two counts never exceed the shorter side');

  assert.deepStrictEqual(trimCommon([], ['a']), { prefix: 0, suffix: 0 });
  assert.deepStrictEqual(trimCommon(['a'], []), { prefix: 0, suffix: 0 });
  assert.deepStrictEqual(trimCommon([], []), { prefix: 0, suffix: 0 });
});

test('s3 the two versions line up on their longest common subsequence', () => {
  const inserted = diffLines('a\nb\nc\n', 'a\nx\nb\nc\n');
  assert.deepStrictEqual(shape(inserted), ['equal|a', 'insert|x', 'equal|b', 'equal|c'], 'one inserted line does not relabel the lines under it');

  const removed = diffLines('a\nb\nc\nd\n', 'a\nd\n');
  assert.deepStrictEqual(shape(removed), ['equal|a', 'delete|b', 'delete|c', 'equal|d']);

  // A positional walk finds one shared line here; the real answer is five.
  const shifted = diffLines('1\n2\n3\n4\n5\n6\n', '1\n3\n4\n5\n6\n7\n');
  assert.deepStrictEqual(shape(shifted), ['equal|1', 'delete|2', 'equal|3', 'equal|4', 'equal|5', 'equal|6', 'insert|7']);

  const nothingShared = diffLines('x\ny\n', 'p\nq\n');
  assert.deepStrictEqual(shape(nothingShared), ['delete|x', 'delete|y', 'insert|p', 'insert|q'], 'a changed run prints the old block before the new one');

  const swapped = diffLines('a\nb\nc\nd\ne\nf\n', 'a\nc\nd\ne\nb\nf\n');
  assert.strictEqual(swapped.filter((op) => op.type === 'equal').length, 5, 'the shared subsequence is as long as it can be');

  // Whatever alignment is chosen, the three streams have to reconstruct.
  const pairs = [
    ['a\nb\nc\nd\ne\n', 'a\nc\nb\ne\nd\n'],
    [text(numbered(12)), text(replaceAt(numbered(12), 5, 'X06'))],
    ['one\ntwo\n', 'one\ntwo\nthree\nfour\n'],
  ];
  for (const [before, after] of pairs) {
    const ops = diffLines(before, after);
    assert.deepStrictEqual(
      ops.filter((op) => op.type !== 'insert').map((op) => op.line),
      splitLines(before),
      'the equals and deletes rebuild the old version'
    );
    assert.deepStrictEqual(
      ops.filter((op) => op.type !== 'delete').map((op) => op.line),
      splitLines(after),
      'the equals and inserts rebuild the new version'
    );
    let seenInsert = false;
    for (const op of ops) {
      if (op.type === 'equal') { seenInsert = false; continue; }
      if (op.type === 'insert') { seenInsert = true; continue; }
      assert.strictEqual(seenInsert, false, 'no deletion follows an insertion inside one changed run');
    }
  }
});

test('s4 an absent or empty version is an empty file', () => {
  assert.deepStrictEqual(diffLines('', ''), [], 'two empty files have nothing between them');
  assert.deepStrictEqual(shape(diffLines('', 'a\nb\n')), ['insert|a', 'insert|b']);
  assert.deepStrictEqual(shape(diffLines('a\nb\n', '')), ['delete|a', 'delete|b']);

  assert.deepStrictEqual(splitLines(null), [], 'a missing version has no lines');
  assert.deepStrictEqual(splitLines(undefined), []);
  assert.deepStrictEqual(shape(diffLines(null, 'a\n')), ['insert|a'], 'a new file is all insertions');
  assert.deepStrictEqual(shape(diffLines('a\n', undefined)), ['delete|a'], 'a deleted file is all deletions');
  assert.deepStrictEqual(diffLines(null, undefined), []);

  assert.deepStrictEqual(shape(diffLines('', '\n')), ['insert|'], 'one empty line is still a line');
  assert.deepStrictEqual(shape(diffLines('\n', '')), ['delete|']);
});

test('s5 hunks keep the neighbourhood of each change and merge when the gap is only context', () => {
  const before = text(numbered(20));
  const oneChange = diffLines(before, text(replaceAt(numbered(20), 9, 'X10')));

  const middle = hunks(oneChange, 3);
  assert.strictEqual(middle.length, 1);
  assert.deepStrictEqual(shape(middle[0].ops), [
    'equal|L07', 'equal|L08', 'equal|L09', 'delete|L10', 'insert|X10', 'equal|L11', 'equal|L12', 'equal|L13',
  ], 'three equal ops either side of the change and no more');

  const atTheTop = hunks(diffLines(before, text(replaceAt(numbered(20), 0, 'X01'))), 3);
  assert.strictEqual(atTheTop.length, 1);
  assert.deepStrictEqual(shape(atTheTop[0].ops), ['delete|L01', 'insert|X01', 'equal|L02', 'equal|L03', 'equal|L04'], 'there is nothing above the first line to pad with');

  const atTheBottom = hunks(diffLines(before, text(replaceAt(numbered(20), 19, 'X20'))), 3);
  assert.strictEqual(atTheBottom.length, 1);
  assert.deepStrictEqual(shape(atTheBottom[0].ops), ['equal|L17', 'equal|L18', 'equal|L19', 'delete|L20', 'insert|X20']);

  // Six equal ops between the two changes: printing them costs the same as
  // cutting, so it stays one hunk. Seven, and it cuts.
  const near = replaceAt(replaceAt(numbered(20), 4, 'X05'), 11, 'X12');
  const merged = hunks(diffLines(before, text(near)), 3);
  assert.strictEqual(merged.length, 1, 'a gap of exactly twice the context does not cut the hunk');
  assert.strictEqual(merged[0].ops.length, 16);

  const far = replaceAt(replaceAt(numbered(20), 4, 'X05'), 12, 'X13');
  const split = hunks(diffLines(before, text(far)), 3);
  assert.strictEqual(split.length, 2, 'a gap of one more than twice the context cuts');
  assert.deepStrictEqual(shape(split[0].ops), ['equal|L02', 'equal|L03', 'equal|L04', 'delete|L05', 'insert|X05', 'equal|L06', 'equal|L07', 'equal|L08']);
  assert.deepStrictEqual(shape(split[1].ops), ['equal|L10', 'equal|L11', 'equal|L12', 'delete|L13', 'insert|X13', 'equal|L14', 'equal|L15', 'equal|L16']);

  const bare = hunks(oneChange, 0);
  assert.strictEqual(bare.length, 1);
  assert.deepStrictEqual(shape(bare[0].ops), ['delete|L10', 'insert|X10'], 'zero context is the change and nothing else');

  const tight = hunks(oneChange, 1);
  assert.deepStrictEqual(shape(tight[0].ops), ['equal|L09', 'delete|L10', 'insert|X10', 'equal|L11']);

  assert.deepStrictEqual(hunks(diffLines(before, before), 3), [], 'a file nobody touched has no hunks');
  assert.deepStrictEqual(hunks([], 3), []);

  const byDefault = hunks(oneChange);
  assert.strictEqual(byDefault.length, 1);
  assert.deepStrictEqual(shape(byDefault[0].ops), shape(middle[0].ops), 'three lines of context when none is given');
  for (const junk of [-1, 2.5, '3', null, NaN, Infinity, true, {}]) {
    const fallback = hunks(oneChange, junk);
    assert.strictEqual(fallback.length, 1, 'an unusable context falls back to three rather than throwing');
    assert.deepStrictEqual(shape(fallback[0].ops), shape(middle[0].ops));
  }
});

test('s6 each hunk carries the line numbers its header needs', () => {
  const before = text(numbered(20));
  const middle = hunks(diffLines(before, text(replaceAt(numbered(20), 9, 'X10'))), 3)[0];
  assert.strictEqual(middle.oldStart, 7);
  assert.strictEqual(middle.oldLines, 7, 'the equals and the deletes are the old side');
  assert.strictEqual(middle.newStart, 7);
  assert.strictEqual(middle.newLines, 7, 'the equals and the inserts are the new side');

  const bare = hunks(diffLines(before, text(replaceAt(numbered(20), 9, 'X10'))), 0)[0];
  assert.strictEqual(bare.oldStart, 10);
  assert.strictEqual(bare.oldLines, 1);
  assert.strictEqual(bare.newStart, 10);
  assert.strictEqual(bare.newLines, 1);

  // A brand new file: the old side contributes nothing, and there is nothing
  // before the hunk either.
  const created = hunks(diffLines('', 'a\nb\n'), 3)[0];
  assert.strictEqual(created.oldStart, 0, 'a side with no lines names what it sits after, and here that is nothing');
  assert.strictEqual(created.oldLines, 0);
  assert.strictEqual(created.newStart, 1);
  assert.strictEqual(created.newLines, 2);

  const emptied = hunks(diffLines('a\nb\n', ''), 3)[0];
  assert.strictEqual(emptied.oldStart, 1);
  assert.strictEqual(emptied.oldLines, 2);
  assert.strictEqual(emptied.newStart, 0);
  assert.strictEqual(emptied.newLines, 0);

  const far = replaceAt(replaceAt(numbered(20), 4, 'X05'), 12, 'X13');
  const two = hunks(diffLines(before, text(far)), 3);
  assert.strictEqual(two.length, 2);
  assert.strictEqual(two[0].oldStart, 2);
  assert.strictEqual(two[0].oldLines, 7);
  assert.strictEqual(two[0].newStart, 2);
  assert.strictEqual(two[0].newLines, 7);
  assert.strictEqual(two[1].oldStart, 10);
  assert.strictEqual(two[1].oldLines, 7);
  assert.strictEqual(two[1].newStart, 10);
  assert.strictEqual(two[1].newLines, 7);

  // Two lines added at the top push the new side's numbering out of step with
  // the old side's for every hunk after them.
  const shifted = ['NEW1', 'NEW2'].concat(replaceAt(numbered(20), 14, 'X15'));
  const drifted = hunks(diffLines(before, text(shifted)), 3);
  assert.strictEqual(drifted.length, 2);
  assert.strictEqual(drifted[0].oldStart, 1);
  assert.strictEqual(drifted[0].oldLines, 3);
  assert.strictEqual(drifted[0].newStart, 1);
  assert.strictEqual(drifted[0].newLines, 5);
  assert.strictEqual(drifted[1].oldStart, 12);
  assert.strictEqual(drifted[1].oldLines, 7);
  assert.strictEqual(drifted[1].newStart, 14, 'the new side is two lines further down the file');
  assert.strictEqual(drifted[1].newLines, 7);
});

test('s7 unified renders the patch', () => {
  assert.strictEqual(
    unified('alpha\nbeta\ngamma\n', 'alpha\nBETA\ngamma\n'),
    '--- a\n+++ b\n@@ -1,3 +1,3 @@\n alpha\n-beta\n+BETA\n gamma\n'
  );

  assert.strictEqual(
    unified('alpha\nbeta\ngamma\n', 'alpha\nBETA\ngamma\n', { oldPath: 'src/old.js', newPath: 'src/new.js' }),
    '--- src/old.js\n+++ src/new.js\n@@ -1,3 +1,3 @@\n alpha\n-beta\n+BETA\n gamma\n'
  );

  for (const junk of [null, '', 42, undefined, {}]) {
    const fallen = unified('alpha\nbeta\n', 'alpha\nBETA\n', { oldPath: junk, newPath: junk });
    assert.strictEqual(fallen.split('\n')[0], '--- a', 'an unusable label falls back');
    assert.strictEqual(fallen.split('\n')[1], '+++ b');
  }

  assert.strictEqual(unified('alpha\nbeta\n', 'alpha\nbeta\n'), '', 'two versions with nothing between them are not a patch');
  assert.strictEqual(unified('', ''), '');
  assert.strictEqual(unified(text(numbered(20)), text(numbered(20))), '');

  assert.strictEqual(
    unified('', 'a\nb\n'),
    '--- a\n+++ b\n@@ -0,0 +1,2 @@\n+a\n+b\n'
  );
  assert.strictEqual(
    unified('a\nb\n', ''),
    '--- a\n+++ b\n@@ -1,2 +0,0 @@\n-a\n-b\n'
  );

  // Both counts are always written out, even when a count is 1.
  assert.strictEqual(unified('only\n', 'ONLY\n'), '--- a\n+++ b\n@@ -1,1 +1,1 @@\n-only\n+ONLY\n');

  const far = replaceAt(replaceAt(numbered(20), 4, 'X05'), 12, 'X13');
  const patch = unified(text(numbered(20)), text(far));
  const headers = patch.split('\n').filter((line) => line.startsWith('@@'));
  assert.deepStrictEqual(headers, ['@@ -2,7 +2,7 @@', '@@ -10,7 +10,7 @@'], 'one header per hunk');
  assert.strictEqual(patch.endsWith('\n'), true, 'the patch ends with a newline');
  assert.strictEqual(patch.split('\n').filter((line) => line.startsWith(' ')).length, 12);
  assert.strictEqual(patch.split('\n').filter((line) => line.startsWith('-') && !line.startsWith('---')).length, 2);
  assert.strictEqual(patch.split('\n').filter((line) => line.startsWith('+') && !line.startsWith('+++')).length, 2);
});

test('s8 the missing final newline is marked', () => {
  const marker = '\\ No newline at end of file';

  assert.strictEqual(
    unified('a\nb\nc', 'a\nb\nC'),
    '--- a\n+++ b\n@@ -1,3 +1,3 @@\n a\n b\n-c\n' + marker + '\n+C\n' + marker + '\n',
    'both versions stop short, and each marks its own last line'
  );

  assert.strictEqual(
    unified('a\nb\nc', 'a\nb\nc\n'),
    '--- a\n+++ b\n@@ -1,3 +1,3 @@\n a\n b\n-c\n' + marker + '\n+c\n',
    'the same text is not the same line when only one side has the newline'
  );

  assert.strictEqual(
    unified('a\nb\nc\n', 'a\nb\nc'),
    '--- a\n+++ b\n@@ -1,3 +1,3 @@\n a\n b\n-c\n+c\n' + marker + '\n'
  );

  assert.strictEqual(
    unified('x\nb\nc', 'y\nb\nc'),
    '--- a\n+++ b\n@@ -1,3 +1,3 @@\n-x\n+y\n b\n c\n' + marker + '\n',
    'one marker on the shared last line, not one for each version'
  );

  // The old version stops short and its last line is kept, but the new version
  // carries on past it.
  assert.strictEqual(
    unified('a\nb', 'a\nb\nc\n'),
    '--- a\n+++ b\n@@ -1,2 +1,3 @@\n a\n b\n' + marker + '\n+c\n'
  );

  assert.strictEqual(unified('a\nb\nc', 'a\nb\nc'), '', 'two versions that stop short in the same place agree');
  assert.strictEqual(unified('solo', 'solo\n'), '--- a\n+++ b\n@@ -1,1 +1,1 @@\n-solo\n' + marker + '\n+solo\n', 'a final newline appearing is a change on its own');
  assert.strictEqual(unified('', 'a'), '--- a\n+++ b\n@@ -0,0 +1,1 @@\n+a\n' + marker + '\n', 'an empty version has no last line to mark');

  // The line the marker belongs to is nowhere near the change, so it is not in
  // the patch and neither is the marker.
  const long = numbered(20);
  const changedTop = replaceAt(long, 0, 'X01');
  const patch = unified(long.join('\n'), changedTop.join('\n'));
  assert.strictEqual(patch.includes(marker), false, 'nothing is marked when the last line is outside every hunk');
  assert.strictEqual(patch, '--- a\n+++ b\n@@ -1,4 +1,4 @@\n-L01\n+X01\n L02\n L03\n L04\n');
});

test('s9 the review summary counts the right way round', () => {
  const added = summarize('a\nb\n', 'a\nb\nc\n');
  assert.strictEqual(added.added, 1, 'a line arriving in the new version is an addition');
  assert.strictEqual(added.removed, 0);
  assert.strictEqual(added.total, 3, 'the line count of the new version, with no phantom row');
  assert.strictEqual(added.hunks, 1);
  assert.strictEqual(added.changed, true);

  const removed = summarize('a\nb\nc\n', 'a\nb\n');
  assert.strictEqual(removed.added, 0);
  assert.strictEqual(removed.removed, 1);
  assert.strictEqual(removed.total, 2);
  assert.strictEqual(removed.hunks, 1);

  const untouched = summarize('a\nb\n', 'a\nb\n');
  assert.deepStrictEqual(
    { added: untouched.added, removed: untouched.removed, total: untouched.total, hunks: untouched.hunks, changed: untouched.changed },
    { added: 0, removed: 0, total: 2, hunks: 0, changed: false }
  );

  const created = summarize(null, 'a\nb\n');
  assert.strictEqual(created.added, 2);
  assert.strictEqual(created.removed, 0);
  assert.strictEqual(created.total, 2);
  assert.strictEqual(created.changed, true);

  const deleted = summarize('a\nb\n', null);
  assert.strictEqual(deleted.added, 0);
  assert.strictEqual(deleted.removed, 2);
  assert.strictEqual(deleted.total, 0);
  assert.strictEqual(deleted.changed, true);

  const before = text(numbered(20));
  const far = replaceAt(replaceAt(numbered(20), 4, 'X05'), 12, 'X13');
  const twoHunks = summarize(before, text(far));
  assert.strictEqual(twoHunks.added, 2);
  assert.strictEqual(twoHunks.removed, 2);
  assert.strictEqual(twoHunks.total, 20);
  assert.strictEqual(twoHunks.hunks, 2, 'two changes far enough apart are two hunks at the default context');

  const near = replaceAt(replaceAt(numbered(20), 4, 'X05'), 11, 'X12');
  assert.strictEqual(summarize(before, text(near)).hunks, 1);
});

test('s10 a carriage return before the newline is part of the ending, not the line', () => {
  assert.deepStrictEqual(splitLines('a\r\nb\r\n'), ['a', 'b']);
  assert.deepStrictEqual(splitLines('a\r\nb'), ['a', 'b'], 'the last line stops without an ending of any kind');
  assert.deepStrictEqual(splitLines('a\r\nb\nc\r\n'), ['a', 'b', 'c'], 'a file can be mixed');
  assert.deepStrictEqual(splitLines('\r\n'), ['']);
  assert.deepStrictEqual(splitLines('a\rb\n'), ['a\rb'], 'a carriage return in the middle of a line is content');
  assert.deepStrictEqual(splitLines('a\r'), ['a\r'], 'nothing followed it, so it is not an ending');
  assert.deepStrictEqual(splitLines('a\r\n\r\nb\r\n'), ['a', '', 'b']);

  assert.deepStrictEqual(shape(diffLines('a\r\nb\r\n', 'a\nb\n')), ['equal|a', 'equal|b'], 'the same file saved two ways has not changed');
  assert.deepStrictEqual(shape(diffLines('a\nb\n', 'a\r\nb\r\n')), ['equal|a', 'equal|b']);
  assert.deepStrictEqual(
    shape(diffLines('one\r\ntwo\r\nthree\r\n', 'one\r\nTWO\r\nthree\r\n')),
    ['equal|one', 'delete|two', 'insert|TWO', 'equal|three']
  );

  assert.strictEqual(
    unified('one\r\ntwo\r\nthree\r\n', 'one\r\nTWO\r\nthree\r\n'),
    '--- a\n+++ b\n@@ -1,3 +1,3 @@\n one\n-two\n+TWO\n three\n',
    'the rendered patch carries no carriage returns'
  );
  assert.strictEqual(unified('a\r\nb\r\n', 'a\nb\n'), '', 'a re-saved file is not a patch');

  assert.strictEqual(
    unified('x\r\ny', 'x\r\ny\r\n'),
    '--- a\n+++ b\n@@ -1,2 +1,2 @@\n x\n-y\n\\ No newline at end of file\n+y\n',
    'the missing ending still shows through a carriage return file'
  );

  const resaved = summarize('a\r\nb\r\n', 'a\nb\n');
  assert.strictEqual(resaved.added, 0);
  assert.strictEqual(resaved.removed, 0);
  assert.strictEqual(resaved.total, 2);
  assert.strictEqual(resaved.changed, false, 'the review list stops shouting about a re-saved file');
});

test('s11 the rendering options', () => {
  const before = text(numbered(20));
  const after = text(replaceAt(numbered(20), 9, 'X10'));

  assert.strictEqual(
    unified(before, after, { context: 1 }),
    '--- a\n+++ b\n@@ -9,3 +9,3 @@\n L09\n-L10\n+X10\n L11\n'
  );
  assert.strictEqual(
    unified(before, after, { context: 0 }),
    '--- a\n+++ b\n@@ -10,1 +10,1 @@\n-L10\n+X10\n'
  );
  for (const junk of [-1, 2.5, '1', null, NaN, true]) {
    assert.strictEqual(unified(before, after, { context: junk }), unified(before, after), 'an unusable context falls back to three');
  }

  assert.strictEqual(
    unified(before, after, { header: false }),
    '@@ -7,7 +7,7 @@\n L07\n L08\n L09\n-L10\n+X10\n L11\n L12\n L13\n'
  );
  assert.strictEqual(unified(before, after, { header: true }).startsWith('--- a\n'), true);
  assert.strictEqual(unified(before, after, { header: 0 }).startsWith('--- a\n'), true, 'only an exact false drops the header');

  assert.strictEqual(
    unified(before, after, { context: 0, compact: true }),
    '--- a\n+++ b\n@@ -10 +10 @@\n-L10\n+X10\n',
    'a count of one loses its comma'
  );
  assert.strictEqual(
    unified(before, after, { compact: true }),
    unified(before, after),
    'counts above one are untouched'
  );
  assert.strictEqual(unified('', 'a\n', { compact: true }), '--- a\n+++ b\n@@ -0,0 +1 @@\n+a\n', 'a count of zero keeps its comma');
  assert.strictEqual(unified(before, after, { context: 0, compact: 'yes' }), unified(before, after, { context: 0 }), 'only an exact true is compact');

  // At zero context a pure insertion holds no line of the old version at all,
  // so its header names the line it goes in after.
  const inserted = numbered(6).slice(0, 4).concat(['NEW1', 'NEW2'], numbered(6).slice(4));
  assert.strictEqual(
    unified(text(numbered(6)), text(inserted), { context: 0 }),
    '--- a\n+++ b\n@@ -4,0 +5,2 @@\n+NEW1\n+NEW2\n'
  );
  assert.strictEqual(
    unified(text(numbered(6)), text(inserted), { context: 0, compact: true }),
    '--- a\n+++ b\n@@ -4,0 +5,2 @@\n+NEW1\n+NEW2\n'
  );

  const dropped = numbered(6).filter((line) => line !== 'L03');
  assert.strictEqual(
    unified(text(numbered(6)), text(dropped), { context: 0 }),
    '--- a\n+++ b\n@@ -3,1 +2,0 @@\n-L03\n'
  );
  assert.strictEqual(
    unified(text(numbered(6)), text(dropped), { context: 0, compact: true, header: false }),
    '@@ -3 +2,0 @@\n-L03\n'
  );
});

