'use strict';

// Line diff for the code review screen. Both versions of a file arrive as one
// string; the screen renders one row per line of whatever comes back.

const DEFAULT_CONTEXT = 3;
const NO_NEWLINE = '\\ No newline at end of file';

// A carriage return only belongs to the line ending when a newline followed it,
// so the last line of a file that stops without one keeps whatever it has.
function splitLines(text) {
  if (text === null || text === undefined) return [];
  const source = String(text);
  if (source === '') return [];
  const closed = source.endsWith('\n');
  const body = closed ? source.slice(0, -1) : source;
  const parts = body.split('\n');
  for (let i = 0; i < parts.length; i += 1) {
    const followed = i < parts.length - 1 || closed;
    if (followed && parts[i].endsWith('\r')) parts[i] = parts[i].slice(0, -1);
  }
  return parts;
}

// An absent or empty version has no last line, so it never wants the marker.
function endsWithNewline(text) {
  if (text === null || text === undefined) return true;
  const source = String(text);
  return source === '' || source.endsWith('\n');
}

function trimCommon(left, right) {
  const a = Array.isArray(left) ? left : [];
  const b = Array.isArray(right) ? right : [];
  const shorter = Math.min(a.length, b.length);
  let prefix = 0;
  while (prefix < shorter && a[prefix] === b[prefix]) prefix += 1;
  const remaining = shorter - prefix;
  let suffix = 0;
  while (suffix < remaining && a[a.length - 1 - suffix] === b[b.length - 1 - suffix]) suffix += 1;
  return { prefix, suffix };
}

// Longest common subsequence over the part of the two versions that the common
// head and tail did not already account for. Deletions are buffered so that a
// run of changes always prints the old block above the new one.
function lcsOps(left, right) {
  const n = left.length;
  const m = right.length;
  const table = [];
  for (let i = 0; i <= n; i += 1) table.push(new Array(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      table[i][j] = left[i] === right[j]
        ? table[i + 1][j + 1] + 1
        : Math.max(table[i + 1][j], table[i][j + 1]);
    }
  }
  const ops = [];
  let dels = [];
  let ins = [];
  const flush = () => {
    for (const line of dels) ops.push({ type: 'delete', line });
    for (const line of ins) ops.push({ type: 'insert', line });
    dels = [];
    ins = [];
  };
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (left[i] === right[j]) {
      flush();
      ops.push({ type: 'equal', line: left[i] });
      i += 1;
      j += 1;
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      dels.push(left[i]);
      i += 1;
    } else {
      ins.push(right[j]);
      j += 1;
    }
  }
  while (i < n) { dels.push(left[i]); i += 1; }
  while (j < m) { ins.push(right[j]); j += 1; }
  flush();
  return ops;
}

function diffLines(a, b) {
  const left = splitLines(a);
  const right = splitLines(b);
  const { prefix, suffix } = trimCommon(left, right);
  const ops = [];
  for (let i = 0; i < prefix; i += 1) ops.push({ type: 'equal', line: left[i] });
  const midLeft = left.slice(prefix, left.length - suffix);
  const midRight = right.slice(prefix, right.length - suffix);
  for (const op of lcsOps(midLeft, midRight)) ops.push(op);
  for (let i = left.length - suffix; i < left.length; i += 1) ops.push({ type: 'equal', line: left[i] });
  return ops;
}

function contextSize(value) {
  if (typeof value === 'number' && Number.isInteger(value) && value >= 0) return value;
  return DEFAULT_CONTEXT;
}

// The 1-based number each op occupies on each side, null where the op does not
// exist on that side.
function positions(ops) {
  const oldAt = [];
  const newAt = [];
  let oldNo = 0;
  let newNo = 0;
  for (const op of ops) {
    if (op.type === 'insert') {
      newNo += 1;
      oldAt.push(null);
      newAt.push(newNo);
    } else if (op.type === 'delete') {
      oldNo += 1;
      oldAt.push(oldNo);
      newAt.push(null);
    } else {
      oldNo += 1;
      newNo += 1;
      oldAt.push(oldNo);
      newAt.push(newNo);
    }
  }
  return { oldAt, newAt };
}

// Index ranges of the op list, one per hunk, context already folded in. Two
// changed runs stay together when the equal ops between them would all have
// been printed as context anyway.
function hunkRanges(ops, size) {
  const changed = [];
  ops.forEach((op, i) => { if (op && op.type !== 'equal') changed.push(i); });
  if (changed.length === 0) return [];
  const runs = [];
  let from = changed[0];
  let to = changed[0];
  for (let k = 1; k < changed.length; k += 1) {
    const at = changed[k];
    if (at - to - 1 <= 2 * size) { to = at; continue; }
    runs.push([from, to]);
    from = at;
    to = at;
  }
  runs.push([from, to]);
  return runs.map(([f, t]) => [Math.max(0, f - size), Math.min(ops.length - 1, t + size)]);
}

function sideSpan(at, from, to) {
  let start = 0;
  let count = 0;
  for (let i = from; i <= to; i += 1) {
    if (at[i] === null) continue;
    if (count === 0) start = at[i];
    count += 1;
  }
  if (count === 0) {
    // Nothing from this side in the hunk, so the header names the line it goes
    // after, which is 0 when there is nothing before it.
    for (let i = from - 1; i >= 0; i -= 1) {
      if (at[i] !== null) { start = at[i]; break; }
    }
  }
  return { start, count };
}

function hunks(ops, context) {
  const list = Array.isArray(ops) ? ops : [];
  const size = contextSize(context);
  const { oldAt, newAt } = positions(list);
  return hunkRanges(list, size).map(([from, to]) => {
    const older = sideSpan(oldAt, from, to);
    const newer = sideSpan(newAt, from, to);
    return {
      ops: list.slice(from, to + 1),
      oldStart: older.start,
      oldLines: older.count,
      newStart: newer.start,
      newLines: newer.count,
    };
  });
}

// The last line of a file that stops without a newline is not the same line as
// the same text followed by one, so a shared final line splits in two when the
// two versions disagree about it.
function opsForPatch(a, b, oldClosed, newClosed) {
  const ops = diffLines(a, b);
  const last = ops[ops.length - 1];
  if (oldClosed !== newClosed && last && last.type === 'equal') {
    ops.pop();
    ops.push({ type: 'delete', line: last.line });
    ops.push({ type: 'insert', line: last.line });
  }
  return ops;
}

function unified(a, b, options) {
  const opts = options && typeof options === 'object' ? options : {};
  const size = contextSize(opts.context);
  const oldClosed = endsWithNewline(a);
  const newClosed = endsWithNewline(b);
  const ops = opsForPatch(a, b, oldClosed, newClosed);
  const groups = hunks(ops, size);
  if (groups.length === 0) return '';
  let lastOld = null;
  let lastNew = null;
  for (const op of ops) {
    if (op.type !== 'insert') lastOld = op;
    if (op.type !== 'delete') lastNew = op;
  }
  const label = (value, fallback) => (typeof value === 'string' && value.length > 0 ? value : fallback);
  const span = (start, count) => (opts.compact === true && count === 1 ? String(start) : start + ',' + count);
  const out = [];
  if (opts.header !== false) {
    out.push('--- ' + label(opts.oldPath, 'a'));
    out.push('+++ ' + label(opts.newPath, 'b'));
  }
  for (const hunk of groups) {
    out.push('@@ -' + span(hunk.oldStart, hunk.oldLines) + ' +' + span(hunk.newStart, hunk.newLines) + ' @@');
    for (const op of hunk.ops) {
      const sign = op.type === 'equal' ? ' ' : (op.type === 'delete' ? '-' : '+');
      out.push(sign + op.line);
      if ((!oldClosed && op === lastOld) || (!newClosed && op === lastNew)) out.push(NO_NEWLINE);
    }
  }
  return out.join('\n') + '\n';
}

function sideBySide(a, b, options) {
  const opts = options && typeof options === 'object' ? options : {};
  const size = contextSize(opts.context);
  const ops = diffLines(a, b);
  const { oldAt, newAt } = positions(ops);
  const rows = [];
  hunkRanges(ops, size).forEach(([from, to], index) => {
    if (index > 0) rows.push({ type: 'gap' });
    let i = from;
    while (i <= to) {
      if (ops[i].type === 'equal') {
        rows.push({
          type: 'equal',
          oldNumber: oldAt[i],
          newNumber: newAt[i],
          oldLine: ops[i].line,
          newLine: ops[i].line,
        });
        i += 1;
        continue;
      }
      const dels = [];
      const ins = [];
      while (i <= to && ops[i].type !== 'equal') {
        if (ops[i].type === 'delete') dels.push(i); else ins.push(i);
        i += 1;
      }
      const paired = Math.min(dels.length, ins.length);
      for (let k = 0; k < paired; k += 1) {
        rows.push({
          type: 'modify',
          oldNumber: oldAt[dels[k]],
          newNumber: newAt[ins[k]],
          oldLine: ops[dels[k]].line,
          newLine: ops[ins[k]].line,
        });
      }
      for (let k = paired; k < dels.length; k += 1) {
        rows.push({
          type: 'delete',
          oldNumber: oldAt[dels[k]],
          newNumber: null,
          oldLine: ops[dels[k]].line,
          newLine: null,
        });
      }
      for (let k = paired; k < ins.length; k += 1) {
        rows.push({
          type: 'insert',
          oldNumber: null,
          newNumber: newAt[ins[k]],
          oldLine: null,
          newLine: ops[ins[k]].line,
        });
      }
    }
  });
  return rows;
}

module.exports = { splitLines, trimCommon, diffLines, hunks, unified, sideBySide };

