'use strict';

const { diffLines, hunks, splitLines } = require('./diff.js');

// The one line summary printed under each file in the review list.
function summarize(before, after) {
  const ops = diffLines(before, after);
  let added = 0;
  let removed = 0;
  for (const op of ops) {
    if (op.type === 'insert') added += 1;
    if (op.type === 'delete') removed += 1;
  }
  return {
    added,
    removed,
    total: splitLines(after).length,
    hunks: hunks(ops).length,
    changed: added + removed > 0,
  };
}

module.exports = { summarize };
